import React from "react";
import { Routes, Route, Navigate } from "react-router-dom";

import Login from "./components/Login/Login";
import ProtectedRoute from "./components/Protected/ProtectedRoute";
import RequireAdmin from "./components/Protected/RequireAdmin";

import AdminLayout from "./components/Admin/AdminLayout";
import UserManagement from "./components/Admin/Usermanagement"; // ĐÚNG case file

const AdminDashboard = () => (
  <div>
    <h2>Admin Dashboard</h2>
    <p>Nếu thấy màn này là routing OK.</p>
  </div>
);

const Forbidden = () => <div style={{ padding: 20 }}>403 - Forbidden</div>;

export default function App() {
  return (
    <Routes>
      <Route path="/login" element={<Login />} />
      <Route path="/forbidden" element={<Forbidden />} />

      <Route element={<ProtectedRoute />}>
        <Route path="/admin" element={<AdminLayout />}>
          {/* QUAN TRỌNG: index route để /admin không trắng */}
          <Route index element={<AdminDashboard />} />

          <Route element={<RequireAdmin />}>
            <Route path="users" element={<UserManagement />} />
          </Route>
        </Route>
      </Route>

      <Route path="/" element={<Navigate to="/login" replace />} />
      <Route path="*" element={<Navigate to="/login" replace />} />
    </Routes>
  );
}
